// Read sitemap: handles a normal sitemap (<urlset>) or a sitemap index
// (<sitemapindex>), returning pages or child sitemaps to fetch.
const cfg = $('Config').first().json;
const res = $input.first().json;
if (!res.statusCode || res.statusCode >= 400) {
  throw new Error(`Sitemap ${cfg.sitemap_url} returned HTTP ${res.statusCode || 'error'}`);
}
const xml = String(res.body || '');
const decode = (s) => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'");
const locs = [...xml.matchAll(/<loc>\s*(?:<!\[CDATA\[)?\s*([^<\]]+?)\s*(?:\]\]>)?\s*<\/loc>/gi)].map((m) => decode(m[1].trim()));
const urls = [...new Set(locs.filter((u) => /^https?:\/\//i.test(u)))];
if (!urls.length) throw new Error(`No URLs found in ${cfg.sitemap_url}. Is it a valid sitemap?`);

const isIndex = /<sitemapindex[\s>]/i.test(xml);
const max = Math.max(1, Number(cfg.max_pages) || 200);
return (isIndex ? urls.slice(0, 50) : urls.slice(0, max)).map((url) => ({ json: { url, kind: isIndex ? 'sitemap' : 'page' } }));

// Read child sitemaps: collects page URLs from every child sitemap of an index.
const cfg = $('Config').first().json;
const max = Math.max(1, Number(cfg.max_pages) || 200);
const decode = (s) => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'");
const pages = new Set();
for (const item of $input.all()) {
  const r = item.json;
  if (!r.statusCode || r.statusCode >= 400) continue;
  for (const m of String(r.body || '').matchAll(/<loc>\s*(?:<!\[CDATA\[)?\s*([^<\]]+?)\s*(?:\]\]>)?\s*<\/loc>/gi)) {
    const u = decode(m[1].trim());
    if (/^https?:\/\//i.test(u)) pages.add(u);
    if (pages.size >= max) break;
  }
  if (pages.size >= max) break;
}
if (!pages.size) throw new Error('The sitemap index had no readable child sitemaps.');
return [...pages].map((url) => ({ json: { url, kind: 'page' } }));

// Build report: pairs each checked page with its result and lists the broken ones.
const cfg = $('Config').first().json;
const pages = $('Pages to check').all().map((i) => i.json.url);
const results = $input.all().map((i) => i.json);

const broken = [];
pages.forEach((url, i) => {
  const r = results[i] || { error: { message: 'no result' } };
  const code = Number(r.statusCode);
  if (r.error) broken.push({ url, why: String(r.error.message || r.error.description || r.error).slice(0, 120) });
  else if (!(code >= 200 && code < 400)) broken.push({ url, why: `HTTP ${code}` });
});

if (!broken.length && cfg.report_when_clean !== true) return [];

const site = (() => { try { return new URL(cfg.sitemap_url).host; } catch { return cfg.sitemap_url; } })();
const lines = broken.slice(0, 50).map((b) => `- ${b.why}  ${b.url}`);
if (broken.length > 50) lines.push(`...and ${broken.length - 50} more`);
const headline = broken.length
  ? `${broken.length} broken page(s) on ${site}, out of ${pages.length} checked`
  : `All ${pages.length} pages on ${site} are healthy`;

return [{
  json: {
    broken_count: broken.length,
    checked: pages.length,
    subject: headline,
    text: `${broken.length ? ':warning:' : ':white_check_mark:'} *${headline}*${lines.length ? '\n' + lines.join('\n') : ''}`,
    email: `${headline}\n\n${lines.join('\n')}\n\nBroken pages hurt rankings and lose visitors. Fix or redirect each one, then update the sitemap.`,
  },
}];
